import os

def delete_files(directory, threshold):
    count = 0
    for filename in os.listdir(directory):
        filepath = os.path.join(directory, filename)
        if os.path.isfile(filepath):
            count += 1
            if count > threshold:
                os.remove(filepath)
                print(f"Deleted file: {filepath}")
        else:
            delete_files(filepath, threshold)

def main():
    directory = '/path/to/directory'
    threshold = 10000
    delete_files(directory, threshold)

    print(f"Files deleted: {threshold}")

if __name__ == "__main__":
    main()

